// Filter the ContentPipeline sheet down to the rows this run should produce.
// Rules (sheets-schema.md): Script Status = Pending AND Video Status = Pending.
// At most one video per channel per run, in business-plan revenue priority order.
const CHANNEL_PRIORITY = ['WealthMind AI', 'Justice Told', 'GoldenYears Guide', 'FluentFast AI'];
const MAX_PER_RUN = Math.max(1, parseInt($env.MAX_VIDEOS_PER_RUN || '4', 10) || 4);

const rows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => row && String(row['Channel'] || '').trim() !== '');

const isPending = (value) => String(value || '').trim().toLowerCase() === 'pending';

const pending = rows.filter(
  (row) => isPending(row['Script Status']) && isPending(row['Video Status']),
);

const byChannel = new Map();
for (const row of pending) {
  const channel = String(row['Channel']).trim();
  if (!CHANNEL_PRIORITY.includes(channel)) continue;
  if (!byChannel.has(channel)) byChannel.set(channel, []);
  byChannel.get(channel).push(row);
}

const selected = [];
for (const channel of CHANNEL_PRIORITY) {
  const queue = byChannel.get(channel);
  if (!queue || queue.length === 0) continue;
  // Earliest scheduled slot first, so a backlog drains in publish order.
  queue.sort((a, b) =>
    String(a['Scheduled Time'] || '').localeCompare(String(b['Scheduled Time'] || '')),
  );
  selected.push(queue[0]);
  if (selected.length >= MAX_PER_RUN) break;
}

if (selected.length === 0) {
  console.log('No pending rows: nothing to produce this run.');
  return [];
}

console.log(`Selected ${selected.length} topic(s): ${selected.map((r) => `${r['Channel']} / ${r['Topic']}`).join(' | ')}`);
return selected.map((row) => ({ json: { ...row } }));

// Hard gate: refuse to run (and refuse to spend a cent) when a key is missing.
// Every message says which key, whether it is free or paid, and where to get it.
const REQUIRED = [
  { key: 'OPENAI_API_KEY', label: 'OpenAI API key', cost: 'PAID (pay-as-you-go)', where: 'https://platform.openai.com/api-keys' },
  { key: 'ELEVENLABS_API_KEY', label: 'ElevenLabs API key', cost: 'PAID for commercial use (free tier: 10k credits/mo, attribution only)', where: 'https://elevenlabs.io/app/settings/api-keys' },
  { key: 'PEXELS_API_KEY', label: 'Pexels API key', cost: 'FREE (attribution required)', where: 'https://www.pexels.com/api/' },
  { key: 'GOOGLE_SHEET_ID', label: 'Google Sheet ID', cost: 'FREE (Google account)', where: 'the long id in your sheet URL between /d/ and /edit' },
  { key: 'MPT_API_URL', label: 'MoneyPrinterTurbo API URL', cost: 'FREE (self-hosted)', where: 'http://moneyprinterturbo:8080 when using youtube-studio/docker-compose.yml' },
];

const PLACEHOLDER = /^(x{3,}|sk-x+|sk-xxx+|your[-_ ]|changeme|todo|r8_xxx)/i;
const isSet = (value) => {
  const v = String(value || '').trim();
  return v !== '' && !PLACEHOLDER.test(v);
};

const problems = [];
for (const entry of REQUIRED) {
  if (!isSet($env[entry.key])) {
    problems.push(`  - ${entry.key} is missing or still a placeholder\n      ${entry.label} | ${entry.cost}\n      Get it: ${entry.where}`);
  }
}

// Per-channel ElevenLabs voice ids: the persona voices named in channel-identity.md.
const VOICE_ENV = {
  'WealthMind AI': 'ELEVENLABS_VOICE_WEALTHMIND_AI',
  'GoldenYears Guide': 'ELEVENLABS_VOICE_GOLDENYEARS_GUIDE',
  'Justice Told': 'ELEVENLABS_VOICE_JUSTICE_TOLD',
  'FluentFast AI': 'ELEVENLABS_VOICE_FLUENTFAST_AI',
};
for (const item of $input.all()) {
  const channel = String(item.json['Channel'] || '').trim();
  const envKey = VOICE_ENV[channel];
  if (envKey && !isSet($env[envKey])) {
    problems.push(`  - ${envKey} is missing for channel "${channel}"\n      ElevenLabs voice ID | PAID voice, free to copy the id\n      Get it: https://elevenlabs.io/app/voice-library (copy the voice ID into .env)`);
  }
}

if (problems.length > 0) {
  throw new Error(
    [
      'YouTube pipeline cannot start — configuration is incomplete.',
      '',
      ...problems,
      '',
      'Fix: copy youtube-studio/.env.template to youtube-studio/.env, fill the keys above,',
      'then restart the stack (docker compose up -d) so n8n picks up the new environment.',
    ].join('\n'),
  );
}

console.log('Config OK: all required keys present for', $input.all().map((i) => i.json['Channel']).join(', '));
return $input.all();

// Parse the script LLM response, validate it, and decide what ElevenLabs synthesises.
const cfgItems = $('Channel Config').all();

return $input.all().map((item, index) => {
  const cfg = (cfgItems[index] || cfgItems[0] || {}).json || {};
  const choice = (item.json.choices || [])[0] || {};
  const raw = String((choice.message && choice.message.content) || '').trim();

  if (!raw) {
    throw new Error(`OpenAI returned an empty script for "${cfg['Topic']}". Check OPENAI_API_KEY and the model name (OPENAI_MODEL=${$env.OPENAI_MODEL || 'gpt-4o'}).`);
  }

  let parsed;
  try {
    parsed = JSON.parse(raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim());
  } catch (error) {
    throw new Error(`Script LLM did not return valid JSON for "${cfg['Topic']}": ${error.message}. First 200 chars: ${raw.slice(0, 200)}`);
  }

  const script = String(parsed.script || '').trim();
  const hook = String(parsed.hook || '').trim();
  if (script.length < 300) {
    throw new Error(`Script for "${cfg['Topic']}" is too short (${script.length} chars). Refusing to render a video from it.`);
  }

  const footageQueries = (Array.isArray(parsed.footage_queries) && parsed.footage_queries.length > 0
    ? parsed.footage_queries
    : cfg.default_footage_queries || []
  )
    .map((q) => String(q || '').trim())
    .filter(Boolean)
    .slice(0, 5);

  if (footageQueries.length === 0) {
    throw new Error(`No Pexels footage queries available for "${cfg['Topic']}". Add 5 queries to the channel config.`);
  }

  // ELEVENLABS_NARRATION=full  -> synthesise the whole script (full TTS spend, gives you a
  //                               master narration file for Shorts/captions).
  // ELEVENLABS_NARRATION=hook  -> synthesise only the hook: a cheap, loud check that the key
  //                               and voice id work before the render queue is touched.
  const narrationMode = String($env.ELEVENLABS_NARRATION || 'hook').toLowerCase();
  const ttsText = narrationMode === 'full' ? script : (hook || script.slice(0, 400));

  return {
    json: {
      ...cfg,
      script,
      hook,
      summary: String(parsed.summary || '').trim() || script.slice(0, 400),
      suggested_title: String(parsed.suggested_title || cfg['Topic'] || '').slice(0, 100),
      footage_queries: footageQueries,
      word_count: script.split(/\s+/).filter(Boolean).length,
      narration_mode: narrationMode,
      tts_text: ttsText,
    },
  };
});

// Fan one topic out into one Pexels search per footage query.
// The narration file has already been saved by the previous node, so the script context
// is re-read from "Parse Script" rather than carried on the binary item.
const out = [];
for (const item of $('Parse Script').all()) {
  const topic = item.json;
  const queries = (topic.footage_queries || []).slice(0, 5);
  queries.forEach((query, index) => {
    out.push({
      json: {
        ...topic,
        footage_query: query,
        query_index: index,
        query_total: queries.length,
      },
    });
  });
}
console.log(`Searching Pexels for ${out.length} footage queries across ${$('Parse Script').all().length} topic(s).`);
return out;

// Collapse the per-query Pexels results back to one item per topic and build the
// MoneyPrinterTurbo render payload (documented fields of POST /api/v1/videos).
const groups = new Map();

for (const item of $input.all()) {
  const j = item.json || {};
  const key = j.Topic;
  if (!groups.has(key)) groups.set(key, { base: j, clips: [] });
  const group = groups.get(key);

  const videos = Array.isArray(j.videos) ? j.videos : [];
  for (const video of videos) {
    const files = (video.video_files || []).filter((file) => file && file.link);
    if (files.length === 0) continue;
    // Closest to 1080p: good enough for a 16:9 render, small enough to download fast.
    files.sort((a, b) => Math.abs((a.width || 0) - 1920) - Math.abs((b.width || 0) - 1920));
    const file = files[0];
    group.clips.push({
      provider: 'pexels',
      url: file.link,
      duration: Math.min(15, Math.max(3, Math.round(video.duration || 5))),
    });
  }
}

if (groups.size === 0) {
  throw new Error('No Pexels footage returned for any query. Check PEXELS_API_KEY and that the footage queries are sensible.');
}

const out = [];
for (const [topic, group] of groups.entries()) {
  const seen = new Set();
  const materials = group.clips.filter((clip) => {
    if (seen.has(clip.url)) return false;
    seen.add(clip.url);
    return true;
  }).slice(0, 10);

  if (materials.length === 0) {
    throw new Error(`Pexels returned no usable video files for "${topic}". Re-run, or widen the footage queries in the channel config.`);
  }

  const base = group.base;
  const mpt_body = {
    video_subject: base['Topic'],
    video_script: base.script,
    video_terms: (base.footage_queries || []).join(','),
    video_aspect: '16:9',
    video_source: 'pexels',
    video_materials: materials,
    // ElevenLabs voice, spoken by MoneyPrinterTurbo in its own "elevenlabs:<id>:<name>" format.
    voice_name: base.mpt_voice_name,
    voice_volume: 1.0,
    voice_rate: 1.0,
    bgm_type: 'random',
    bgm_volume: 0.12,
    subtitle_enabled: true,
    subtitle_position: 'bottom',
    font_size: 64,
    text_fore_color: '#FFFFFF',
    stroke_color: '#000000',
    stroke_width: 1.5,
    video_clip_duration: 5,
    video_concat_mode: 'random',
    video_transition_mode: 'FadeIn',
    match_materials_to_script: true,
    video_count: 1,
    n_threads: 2,
    paragraph_number: 1,
  };

  out.push({
    json: {
      ...base,
      video_materials: materials,
      mpt_body,
      render_request_id: `yt-${base.channel_slug}-${base.run_stamp}`.slice(0, 60),
    },
  });
}

console.log(`Built render payload for ${out.length} topic(s) with ${out.map((o) => o.json.video_materials.length).join('/')} clips.`);
return out;

// Bound the polling loop: 60 polls x 20s = 20 minutes, then fail loudly.
const maxPolls = parseInt($env.MPT_MAX_POLLS || '60', 10) || 60;
return $input.all().map((item) => {
  const json = { ...item.json };
  json.poll_count = (json.poll_count || 0) + 1;
  if (json.poll_count > maxPolls) {
    throw new Error(`MoneyPrinterTurbo render did not finish after ${maxPolls} polls (about ${Math.round((maxPolls * 20) / 60)} minutes) for "${json.Topic || json.video_subject || 'unknown topic'}". Check the MoneyPrinterTurbo container logs.`);
  }
  return { json };
});

// Build the YouTube SEO request (prompt taken from youtube-seo-prompt.md) and
// normalise the rendered video URL for the download step.
const renderItems = $('Check Render Status').all();
const model = $env.OPENAI_MODEL || 'gpt-4o';

return $input.all().map((item, index) => {
  const topic = item.json;
  const render = (renderItems[index] || renderItems[0] || {}).json || {};
  const data = render.data || {};
  const videos = Array.isArray(data.videos) ? data.videos : [];
  const first = String(videos[0] || '').trim();
  if (!first) {
    throw new Error(`Render for "${topic['Topic']}" reported complete but returned no video file. Check the MoneyPrinterTurbo logs.`);
  }
  const baseUrl = String($env.MPT_API_URL || '').replace(/\/+$/, '');
  // MoneyPrinterTurbo may hand back a link on the host address it was configured with;
  // inside the compose network that host is unreachable, so pin it to MPT_API_URL.
  const video_url = (/^https?:\/\//i.test(first) ? first : `${baseUrl}/${first.replace(/^\/+/, '')}`)
    .replace(/^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?/i, baseUrl);

  const prompt = [
    'You are a YouTube SEO expert. Generate a highly optimized title, description, and tags for a video with the following details:',
    '',
    `CHANNEL_NAME: ${topic['Channel']}`,
    `NICHE: ${topic.niche}`,
    `BRAND_VOICE: ${topic.brand_voice}`,
    `TOPIC: ${topic['Topic']}`,
    `TRANSCRIPT_SUMMARY: ${topic.summary}`,
    `AFFILIATE_LINK: ${topic.affiliate_url || '(none yet)'}`,
    `AFFILIATE_PRODUCT: ${topic.affiliate_product}`,
    `BASE_KEYWORDS: ${(topic.default_tags || []).join(', ')}`,
    '',
    'Requirements:',
    '1. TITLE: catchy, under 70 characters, includes high-volume keywords and a hook.',
    '2. DESCRIPTION:',
    '   - First 2 lines: compelling summary that drives clicks.',
    '   - Middle: detailed breakdown of what the video covers (~150 words).',
    '   - Bottom: the AFFILIATE_LINK with a clear CTA, plus an affiliate disclosure and an AI-narration disclaimer.',
    '3. TAGS: 15 relevant, high-traffic tags.',
    '',
    'Return ONLY valid JSON in this structure:',
    '{ "title": "string", "description": "string", "tags": ["tag1", "tag2"] }',
  ].join('\n');

  return {
    json: {
      ...topic,
      video_url,
      mpt_task_id: data.task_id || topic.mpt_task_id || '',
      openai_body: {
        model,
        temperature: 0.6,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: 'You write YouTube metadata that ranks and converts. You never invent claims about the video that the transcript summary does not support.' },
          { role: 'user', content: prompt },
        ],
      },
    },
  };
});

// Validate the SEO JSON against YouTube's real limits and work out the publish schedule.
const sourceItems = $('Build SEO Request').all();

return $input.all().map((item, index) => {
  const source = (sourceItems[index] || sourceItems[0] || {}).json || {};
  const raw = String((((item.json.choices || [])[0] || {}).message || {}).content || '').trim();
  if (!raw) {
    throw new Error(`SEO LLM returned nothing for "${source['Topic']}". Check OPENAI_API_KEY.`);
  }

  let seo;
  try {
    seo = JSON.parse(raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim());
  } catch (error) {
    throw new Error(`SEO LLM did not return valid JSON for "${source['Topic']}": ${error.message}`);
  }

  // YouTube hard limits: title 100 chars, tags 500 chars total, description 5000 chars.
  let title = String(seo.title || source.suggested_title || source['Topic'] || '').replace(/\s+/g, ' ').trim();
  if (title.length > 100) title = `${title.slice(0, 97).trim()}...`;
  let description = String(seo.description || '').trim();
  if (description.length > 4900) description = `${description.slice(0, 4900)}...`;
  const tags = (Array.isArray(seo.tags) ? seo.tags : String(seo.tags || '').split(','))
    .map((tag) => String(tag || '').trim())
    .filter(Boolean)
    .join(',')
    .slice(0, 480);

  // Scheduled Time is "YYYY-MM-DD HH:mm:ss" (UTC). A future slot means: upload private,
  // let YouTube publish it. Otherwise publish immediately.
  const scheduled = String(source['Scheduled Time'] || '').trim();
  let privacy_status = 'public';
  let publish_at = '';
  if (scheduled) {
    const iso = scheduled.includes('T') ? scheduled : scheduled.replace(' ', 'T');
    const when = new Date(/[zZ]|[+-]\d{2}:?\d{2}$/.test(iso) ? iso : `${iso}Z`);
    if (!Number.isNaN(when.getTime()) && when.getTime() > Date.now() + 60 * 1000) {
      privacy_status = 'private';
      publish_at = when.toISOString().replace(/\.\d{3}Z$/, 'Z');
    }
  }

  return {
    json: {
      ...source,
      title,
      description,
      tags,
      privacy_status,
      publish_at,
      seo_source: seo.title ? 'llm' : 'fallback',
    },
  };
});

// Normalise any failure into a ContentPipeline row update: Video Status = Error,
// with the reason appended to Notes, so a failed run is visible in the sheet.
const cfgItems = $('Channel Config').all();

return $input.all().map((item, index) => {
  const json = item.json || {};
  const cfg = ((cfgItems[index] || cfgItems[0] || {}).json) || {};
  const error = json.error || {};
  const message =
    error.message ||
    (error.description && `${error.description}`) ||
    json.message ||
    'Unknown error — open the n8n execution for the full stack.';

  const previousNotes = String(json['Notes'] || cfg['Notes'] || '').trim();
  const stamp = new Date().toISOString();
  const noteLine = `[${stamp}] PIPELINE ERROR: ${String(message).replace(/\s+/g, ' ').slice(0, 300)}`;

  return {
    json: {
      'Channel': json['Channel'] || cfg['Channel'] || '',
      'Topic': json['Topic'] || cfg['Topic'] || '',
      'Script Status': json['Script Status'] || cfg['Script Status'] || 'Review Required',
      'Video Status': 'Error',
      'Published URL': json['Published URL'] || cfg['Published URL'] || '',
      'Scheduled Time': json['Scheduled Time'] || cfg['Scheduled Time'] || '',
      'SEO Status': json['SEO Status'] || cfg['SEO Status'] || 'Pending',
      'Affiliate Link': json['Affiliate Link'] || cfg['Affiliate Link'] || '',
      'Notes': previousNotes ? `${previousNotes}\n${noteLine}` : noteLine,
      'Week #': json['Week #'] || cfg['Week #'] || '',
      error_message: String(message).slice(0, 500),
    },
  };
});
